answer_rng.shuffle(answer_positions)
g=9.81;h=6.63e-34;e=1.60e-19;c=3.00e8;me=9.11e-31;R=8.31;sigma=5.67e-8;ke=8.99e9
def ck(name,actual,expected,tol=1e-8):
    v=a.check(name,float(actual),float(expected),tol)
    if current is not None:current['checks'].append(a.checks[-1])
    return v
def begin(identity):
    global current
    current={'id':identity,'checks':[]};records.append(current)
def src(page,q,focus,doc='2.pdf'):return anchor(doc,page,q,focus)
def white_background(figure):
    return re.sub(r'(<svg\b[^>]*>)',r'\1<rect width="100%" height="100%" fill="white"/>',figure,count=1) if figure else None
def mc(n,title,code,stem,opts,key,work,page,sourceq,figure=None,level='core',change=None):
    stem=stem.replace("\\'", "'");work=work.replace("\\'", "'")
    # Balance positions reproducibly, while retaining every physical option.
    # Remap the explanatory distractor labels outside LaTeX at the same time.
    target=answer_positions[n-1]
    others=[i for i in range(4) if i!='ABCD'.index(key)]
    random.Random(f'physics-hl-A-distractors-{n}').shuffle(others)
    order=[]
    for label in 'ABCD':order.append('ABCD'.index(key) if label==target else others.pop())
    mapping={'ABCD'[old]:'ABCD'[new] for new,old in enumerate(order)}
    fragments=re.split(r'(\$[^$]*\$)',work)
    for i in range(0,len(fragments),2):
      # These two sentence-initial A's are articles, not option labels.
      fragments[i]=re.sub(r'\b([ABCD])\b(?! (?:constant|cooler)\b)',lambda m:mapping[m.group(1)],fragments[i])
    work=''.join(fragments);opts=[opts[i] for i in order];key=target
    figure=white_background(figure)
    q=a.mcq(n,title,code,stem,opts,key,work,src(page,sourceq,title),change or 'New physical setup and givens; altered inference, recomputed options and explanation; original scientific figure where useful.',figure,level)
    q['verification']['notes']='Fresh named evidence and scientific reasoning are recorded for '+q['id']+'. Each distractor is explicitly distinguished in the worked marking point.'
    current.update(question=q['id'],section='1A',number=n,analyticalReview=work,optionLabelsDistinct=True)
    mcqs.append(q);return q
def axisbody(xlabel='x',ylabel='y',w=600,h_=260):return line(70,h_-45,w-30,h_-45)+line(70,h_-45,70,25)+text(w-35,h_-20,xlabel)+text(20,25,ylabel)
def fielddots(x0=90,x1=510,y0=50,y1=210,into=False):
    s=''
    for x in range(x0,x1+1,60):
      for y in range(y0,y1+1,50):
        s+=circle(x,y,6)
        s+=(line(x-3,y-3,x+3,y+3)+line(x-3,y+3,x+3,y-3)) if into else f'<circle cx="{x}" cy="{y}" r="2" fill="#202020"/>'
    return s
def charges(q1='+Q',q2='−4Q',label='3d'):
    return svg(line(60,145,550,145)+circle(200,145,22,q1)+circle(440,145,22,q2)+text(200,190,'x = 0',14,'middle')+text(440,190,'x = '+label,14,'middle'),600,240)
def resistor(x,y,w=65,label='R'):
    return line(x-20,y,x,y)+rect(x,y-10,w,20)+line(x+w,y,x+w+20,y)+text(x+w/2,y-20,label,14,'middle')

