# Written question authoring follows. It is deliberately generated from the same
# canonical data as the figures and the private worked marking points.
written=[]; data_questions=[]

def wq(section,n,title,code,stem,parts,solutions,source,figure,level='core',refs=None,changes=None):
    figure=white_background(figure)
    q=a.written(section,n,title,code,stem.replace("\\'", "'"),parts,solutions,source,changes or 'New experimental or physical configuration, new data and multi-stage inference; all results and the scientific SVG freshly recomputed.',figure,level)
    if refs:q['syllabusRefs']=refs
    for group in q['markScheme']:
      for step in group['steps']:step['text']=step['text'].replace("\\'", "'")
    q['verification']['notes']='Every named calculation, sign/domain assumption and worked part is recorded under '+q['id']+'. An independent fresh solution is still required.'
    current.update(question=q['id'],section=section,number=n,partReviews=[{'part':p['label'],'marks':p['marks'],'authorDerivation':[s['text'] for s in m['steps']],'additiveMarkCodeSum':sum(int(s['code'][1:]) for s in m['steps'])} for p,m in zip(q['parts'],q['markScheme'])])
    (data_questions if section=='1B' else written).append(q);return q

