ck('A2Q3a cycle work',W,600);ck('A2Q3b constant-volume heat input',qab,600);ck('A2Q3b constant-pressure heat input',qbc,2250);ck('A2Q3b total heat input',qin,2850);ck('A2Q3c efficiency',W/qin,4/19);ck('A2Q3d entropy production',-qin/1000+qout/100,19.65)
