fig=plot([(2.2,1.24*2.2-2.6),(4.5,1.24*4.5-2.6)],(2,4.6),(0,3.1),'X = (1/λ) / (10⁶ m⁻¹)','stopping potential / V',[2,2.5,3,3.5,4,4.5],[0,1,2,3])
wq('2',6,'A reciprocal-wavelength photoelectric fit','E.2',r'''A vacuum photocell is illuminated by monochromatic light. A model experimental fit over its emitting range is
$$V_s=(1.240\,\mathrm V)X-2.600\,\mathrm V,\qquad X=\frac{1/\lambda}{10^6\,\mathrm{m^{-1}}}.$$
The plotted $V_s$ is the magnitude of the stopping potential. Use $e=1.60\times10^{-19}\,\mathrm C$ and $c=3.00\times10^8\,\mathrm{m\,s^{-1}}$. In part(d) use accepted values $h=6.63\times10^{-34}\,\mathrm{J\,s}$ and $m_e=9.11\times10^{-31}\,\mathrm{kg}$. Assume independent single-photon emission and no space-charge limitation.''',[
('a',r'Use the fit and the photoelectric equation to determine the experimental Planck constant and the metal work function in electronvolts.',3),
('b',r'Determine the threshold wavelength predicted by the fit.',2),
('c',r'At $300\,\mathrm{nm}$ the optical power is increased by a factor4 without changing wavelength. Predict the saturation-current and stopping-potential changes, with reasons.',2),
('d',r'Determine the de Broglie wavelength of the most energetic electrons emitted under $300\,\mathrm{nm}$ illumination.',3)
],[('a',[('M1',r'From $eV_s=hc/\lambda-\Phi$ and $1/\lambda=10^6X$, the fitted slope is $10^6hc/e$.'),('A1',r'$h_{exp}=1.240e/(10^6c)=6.61333\times10^{-34}\,\mathrm{J\,s}$.'),('A1',r'The intercept gives $\Phi/e=2.600\,\mathrm V$, hence work function $2.600\,\mathrm{eV}$.')]),
('b',[('M1',r'Set $V_s=0$: $X_0=2.600/1.240=2.09677$.'),('A1',r'$\lambda_0=1/(10^6X_0)=4.76923\times10^{-7}\,\mathrm m\approx477\,\mathrm{nm}$.')]),
('c',[('R1',r'At fixed wavelength, four times the power means four times the photon arrival rate and therefore four times the saturation current under the assumptions.'),('R1',r'The photon energy and work function are unchanged, so the maximum electron kinetic energy and stopping potential are unchanged.')]),
('d',[('M1',r'The fit at $X=1/(300\times10^{-9}\times10^6)=3.33333$ gives $V_s=1.53333\,\mathrm V$ and $K_{max}=eV_s$.'),('M1',r'$p=\sqrt{2m_eK_{max}}$ and $\lambda_{dB}=h/p$.'),('A1',r'$\lambda_{dB}\approx9.92\times10^{-10}\,\mathrm m=0.992\,\mathrm{nm}$, using unrounded values.')])],
[src(15,'6','Stopping potential, wavelength and quantum inference','1.pdf'),src(16,'6a-c','Threshold and intensity reasoning','1.pdf'),src(20,'36','Accelerated-particle momentum and deBroglie relation')],fig,'ahl')

