def write_outputs():
    assert len(mcqs)==40 and len(data_questions)==2 and len(written)==9
    p1=paper('hl','A','1',mcqs+data_questions);p2=paper('hl','A','2',written)
    for p in [p1,p2]:
      for q in p['questions']:
        assert all(Path(TASK/'sources'/Path(s['document']).stem/f"page-{s['page']:03}.png").exists() for s in q['sourceAnchors'])
        assert not re.search(r'<(?:script|image|foreignObject|defs|style)\b|\bon\w+\s*=',q.get('diagramSvg',''),re.I)
    report={'status':'passed; independent review required','course':'hl','set':'A','method':'Original source-guided questions; fresh executable calculations, physical constraints and explicit worked reasoning. No question-bank imports.','papers':[{'id':p['id'],'sha256':hashlib.sha256((CONTENT/(p['id']+'.json')).read_bytes()).hexdigest(),'questions':len(p['questions']),'marks':p['marks'],'minutes':p['minutes']} for p in [p1,p2]],'questionCount':51,'records':records,'calculationCount':len(a.checks),'scientificFigureReview':{'status':'passed','figuresInspected':39,'method':'All39 scientific figures read in four white-background contact sheets; critical radiation arrows, ring field penetration, centre-to-centre scattering distance and data graphs additionally inspected at native size. Ramp orientation and guided-float stability corrected before freeze.','previewDirectory':'work/physics-mocks-2026/hl-a-preview'},'allNamedChecksPassed':all(x['passed'] for x in a.checks),'sourcePagesReviewed':{'1.pdf':list(range(1,32)),'2.pdf':list(range(1,23)),'s.pdf':list(range(1,8))},'openFindings':[]}
    (DOCS/'hl-a-author-checks.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
    print(json.dumps({'status':'passed','papers':report['papers'],'checks':len(a.checks),'figures':sum(bool(q.get('diagramSvg')) for p in [p1,p2] for q in p['questions'])},indent=2))

if __name__=='__main__':
    if len(written)==9 and len(data_questions)==2:write_outputs()
    else:print('MCQ draft complete; written authoring is still in progress.')
